import numpy as np

def make_obs(agent, prev_agent, obj, prev_obj, reward=None, obstacle=None):
    x = np.zeros((10, 10, 5), dtype=float)
    # wall border in obstacle channel
    x[0, :, 3] = 1
    x[9, :, 3] = 1
    x[:, 0, 3] = 1
    x[:, 9, 3] = 1
    if agent is not None:
        x[agent[0], agent[1], 0] = 1
    if obj is not None:
        x[obj[0], obj[1], 1] = 1
    if reward is not None:
        for r, c in reward:
            x[r, c, 2] = 1
    if obstacle is not None:
        for r, c in obstacle:
            x[r, c, 3] = 1
    if prev_agent is not None:
        x[prev_agent[0], prev_agent[1], 4] = 1
    if prev_obj is not None:
        x[prev_obj[0], prev_obj[1], 4] = 1
    return x.reshape(-1)

def softmax(z):
    z = z - z.max(axis=1, keepdims=True)
    e = np.exp(z)
    return e / e.sum(axis=1, keepdims=True)

agent = (8, 4)
rows = []
labels = []
for c in range(1, 9):
    for name, prev_r in [("down", 5), ("up", 7)]:
        rows.append(make_obs(agent, agent, (6, c), (prev_r, c)))
        labels.append((c, name))

X = np.array(rows)
Y = forward(X)
P = softmax(Y)

print("agent=(8,4), object current=(6,c), prev row=5(down) or 7(up)")
for (c, name), p in zip(labels, P):
    print(f"c={c} {name:4s} noop={p[0]:.2f} up={p[1]:.2f} down={p[2]:.2f} left={p[3]:.2f} right={p[4]:.2f} argmax={int(np.argmax(p))}")
